import {roles,roleLabels,bars,bonds,accounts,approvals,settlements,cases,events,fxRates,repoTrades,goldFinancing} from "./data.js";
const $=(s,r=document)=>r.querySelector(s), esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])), money=(n,c="USD")=>new Intl.NumberFormat("en-US",{style:"currency",currency:c,maximumFractionDigits:0}).format(n);
let persona="operator",page="Dashboard",toastTimer;
const alias={"Executive dashboard":"Dashboard","Executive Treasury Dashboard":"Dashboard","Bank Treasury Dashboard":"Dashboard","Bullion Desk Dashboard":"Dashboard","Vault Dashboard":"Dashboard","Settlement Dashboard":"Dashboard","Supervisory Dashboard":"Dashboard","Audit Dashboard":"Dashboard","Reserve overview":"Dashboard","Bond portfolio":"Government bonds","Gold Market":"Gold & bullion","Bar inventory":"Gold & bullion","Cash Accounts":"Settlement accounts","DvP Monitor":"Settlement monitor","Vault inventory":"Custody & vaults","Audit evidence":"Audit center","Compliance dashboard":"Compliance"};
const icons={"Dashboard":"▦","Tasks & approvals":"▣","Gold & bullion":"◈","Government bonds":"▤","Settlement accounts":"▧","Settlement monitor":"◷","Custody & vaults":"⬡","Risk & limits":"⌁","Compliance":"◇","Audit center":"≋","Reserve overview":"◉","Reports":"▥","FX & money markets":"⇄","Repo & collateral":"⌗","Gold financing":"◆"};
function toast(message,kind="info"){const root=$("#toastRegion");root.innerHTML=`<div class="toast toast-${kind}"><span>${kind==="success"?"✓":"i"}</span><div>${esc(message)}</div><button data-action="dismiss" aria-label="Dismiss">×</button></div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>root.replaceChildren(),3600)}
function badge(text,tone="neutral"){return `<span class="badge badge-${String(tone).toLowerCase().replace(/[^a-z]+/g,"-")}"><i></i>${esc(text)}</span>`}
function btn(text,action,style="secondary",ico=""){return `<button class="button button-${style}" data-action="${action}">${ico?`<span>${ico}</span>`:""}${esc(text)}</button>`}
function heading(kicker,title,desc,actions=""){return `<div class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="heading-actions">${actions}</div></div>`}
function source(text="Synthetic fixture · indicative values · USD unless noted"){return `<div class="source-note"><span class="source-dot"></span>${esc(text)}<span>As of 05 Oct 2026 · 10:42 UTC</span></div>`}
function table(heads,rows){return `<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows||`<tr><td colspan="${heads.length}" class="empty-state">No matching synthetic records.</td></tr>`}</tbody></table></div>`}
function linkRecord(id,label="Details"){return `<button class="row-link" data-action="record" data-id="${esc(id)}">${esc(label)} ↗</button>`}
function stat(label,value,meta,ico,tone="blue"){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${tone}">${ico}</span></div><strong class="stat-value">${value}</strong><div class="stat-meta">${meta}</div></article>`}
function scopeBars(){if(persona==="commercial")return bars.filter(x=>x.owner==="Meridian Commercial Bank");if(persona==="bullion")return bars.filter(x=>x.owner==="Auric Bullion Bank");if(persona==="custodian")return bars.filter(x=>["Zurich Vault 02","London Vault 01"].includes(x.vault));if(persona==="regulator")return bars;if(persona==="auditor"||persona==="operator"||persona==="governor")return bars.filter(x=>x.owner==="Central Reserve Bank");return bars.filter(x=>x.owner==="Central Reserve Bank")}
function scopedPhase2(){const dealing=["operator","commercial","bullion"];return dealing.includes(persona)?{fx:fxRates,repo:repoTrades,fin:goldFinancing}:{fx:[],repo:[],fin:[]}}
function renderContext(){const r=roles[persona],initials=r.name.replaceAll(".","").split(/\s+/).map(s=>s[0]).join("");$("#sideInstitution").innerHTML=`<span class="institution-avatar">${esc(r.org.slice(0,2).toUpperCase())}</span><span><strong>${esc(r.org)}</strong><small>${esc(r.unit)}</small></span><span class="institution-chevron">⌄</span>`;$("#sidebarUser").innerHTML=`<span class="avatar avatar-small">${initials}</span><span><strong>${esc(r.name)}</strong><small>${esc(r.title)}</small></span><span class="online-dot"></span>`;$("#topAvatar").textContent=initials;$("#topName").textContent=r.name;$("#topRole").textContent=r.title;$("#contextStrip").innerHTML=`<div class="context-chip"><span>INSTITUTION</span><strong>${esc(r.org)}</strong></div><div class="context-chip"><span>ROLE & SCOPE</span><strong>${esc(r.title)} · ${esc(r.unit.split("·")[0].trim())}</strong></div><div class="context-chip"><span>ENVIRONMENT</span><strong><i class="env-dot"></i>Sandbox</strong></div><div class="context-chip"><span>ACCESS · DEMO ONLY</span><strong>${esc(r.permissions)}</strong></div><div class="context-chip"><span>CLASSIFICATION · CURRENCY</span><strong>Synthetic demo · USD</strong></div><div class="context-chip context-refresh"><span>DATA SOURCE · AS OF</span><strong><i class="refresh-dot"></i>Demo fixture · 10:42 UTC</strong></div>`}
function renderNav(){const list=roles[persona].nav;$("#navigation").innerHTML=list.map(item=>{const target=alias[item]||item;return `<button class="nav-item ${page===target?"active":""}" data-nav="${esc(item)}"><span class="nav-icon">${icons[item]||"·"}</span><span>${esc(item)}</span>${item==="Tasks & approvals"&&persona!=="auditor"?`<span class="nav-count">3</span>`:""}</button>`}).join("")+`<div class="nav-caption nav-caption-lower">ROADMAP</div><button class="nav-item nav-disabled" data-nav="Phase 2 workspaces"><span class="nav-icon">◌</span><span>Phase 2 workspaces</span><span class="lock-mini">⌑</span></button>`;$("#currentCrumb").textContent=page}
function scopedApprovals(){
 const byRole={
  commercial:[{id:"APR-MCB-0041",title:"Gold position inventory check",detail:"Client allocation · Meridian Commercial Bank",amount:"$1.2M",requester:"L. Chen",age:"24 min ago",risk:"Low",status:"Pending review",evidence:"INV-MCB-0008"}],
  bullion:[{id:"APR-ABB-0088",title:"Allocated bullion quote request",detail:"Sample 800 fine oz · institutional client",amount:"$2,625,000",requester:"S. Laurent",age:"11 min ago",risk:"Medium",status:"Pending review",evidence:"RFQ-ABB-0088"}],
  custodian:[{id:"INS-2025-0041",title:"Vault inspection record",detail:"Zurich Vault 02 · physical count evidence",amount:"—",requester:"E. Mensah",age:"1 hr ago",risk:"Low",status:"Pending review",evidence:"INS-2025-0041"}],
  settlement:[{id:"STL-2025-03812",title:"Custody confirmation exception",detail:"Vault transfer · eight bars · evidence pending",amount:"—",requester:"R. Silva",age:"32 min ago",risk:"Elevated",status:"Pending review",evidence:"STL-2025-03812"}],
  regulator:[{id:"CMP-2025-0082",title:"Request source-of-gold evidence",detail:"Auric Bullion Bank · supervisory sample",amount:"—",requester:"N. Diallo",age:"44 min ago",risk:"Medium",status:"Pending review",evidence:"CMP-2025-0082"}],
  auditor:[{id:"AUD-2025-0017",title:"Verify custody evidence sample",detail:"Zurich Vault 02 · read-only workpaper",amount:"—",requester:"J. Patel",age:"18 min ago",risk:"Low",status:"Evidence review",evidence:"INS-2025-0041"}]
 };
 if(persona==="governor")return approvals.filter(x=>x.id==="APR-2025-0194");
 return byRole[persona]||approvals;
}
function dashboard(){
 const titles={operator:"Reserve operations at a glance",governor:"Executive reserve overview",commercial:"Bank treasury dashboard",bullion:"Bullion desk overview",custodian:"Custody operations overview",settlement:"Settlement operations overview",regulator:"Supervisory overview",auditor:"Audit evidence overview"};
 const metrics={
  operator:[["Total official reserves","$18.42B","Indicative · USD equivalent","◉","blue"],["Monetary gold","$8.76B","6.84M fine oz · allocated","◈","gold"],["Sovereign bonds","$7.21B","12 sample positions","▤","violet"],["Available liquidity","$2.45B","3 synthetic accounts","▧","green"]],
  governor:[["Official reserves","$18.42B","Indicative · USD equivalent","◉","blue"],["Monetary gold","$8.76B","6.84M fine oz · allocated","◈","gold"],["Sovereign bonds","$7.21B","12 sample positions","▤","violet"],["Approvals pending","03","Sample governor review queue","▣","green"]],
  commercial:[["Treasury positions","$2.84B","Meridian · sample only","◉","blue"],["Gold inventory","$820M","Allocated · indicative","◈","gold"],["Bond inventory","$1.12B","6 sample positions","▤","violet"],["Settlement exceptions","01","Illustrative monitor","◷","green"]],
  bullion:[["Desk inventory","$1.56B","Indicative · mixed allocation","◉","blue"],["Allocated gold","486,204 oz","Synthetic bar registry","◈","gold"],["Open quote requests","04","Synthetic RFQ inbox","▤","violet"],["Counterparty exposure","71%","Illustrative desk limit","⌁","green"]],
  custodian:[["Vault locations","02","Sample directory","⬡","blue"],["Bars in sample","1,130","Illustrative inventory","◈","gold"],["Fine weight","439,684 oz","Synthetic custody records","▤","violet"],["Evidence reviews","03","No physical confirmation","▣","green"]],
  settlement:[["Cash accounts","03","Synthetic account records","▧","blue"],["Reserved cash","$250M","Illustrative only","◉","gold"],["In-flight records","01","No active payment rail","◷","violet"],["Sample exceptions","02","Review evidence only","!","green"]],
  regulator:[["Institutions in sample","08","Supervisory fixture","▦","blue"],["Open review cases","03","Synthetic case register","◇","gold"],["Settlement exceptions","02","Aggregated sample status","◷","violet"],["Risk alerts","02","Illustrative thresholds","⌁","green"]],
  auditor:[["Audit sample events","04","Local fixture · not immutable","≋","blue"],["Evidence references","04","Synthetic linked records","▣","gold"],["Bars in assignment","04","Read-only sample scope","◈","violet"],["Workpaper reviews","01","No approval permissions","◇","green"]]
 };
 const r=roles[persona],viewMetrics=metrics[persona],restricted=["governor","auditor","regulator","custodian","settlement"].includes(persona);
 const action=restricted?btn(persona==="auditor"?"Open audit center":"Review tasks & evidence",persona==="auditor"?"goto-audit":"goto-tasks","secondary","≋"):btn("Request a gold quote","rfq","primary","＋");
 const work=scopedApprovals(),workLabel=persona==="auditor"?"Assigned evidence review":persona==="regulator"?"Supervisory task queue":persona==="custodian"?"Custody review queue":persona==="settlement"?"Settlement exceptions":"Tasks & approvals";
 const settlementScope=persona==="auditor"?"Evidence sample only · read-only scope":"Simulated; no payment instruction exists.";
 const gold=persona==="auditor"?settlements[2]:persona==="commercial"?settlements[1]:settlements[0];
 return `${heading("MONDAY, 05 OCTOBER 2026",titles[persona],"A role-scoped view of today's sample records and operational priorities.",`${btn("Export briefing","export")}${action}`)}<div class="page-intro-row"><div class="live-indicator"><span></span> DEMO WORKSPACE ACTIVE</div><div class="page-intro-note">Synthetic sample data · <span>valuation indicative</span></div></div><div class="stat-grid">${viewMetrics.map(x=>stat(x[0],x[1],x[2],x[3],x[4])).join("")}</div><div class="dashboard-grid"><div class="main-stack"><div class="chart-card"><div class="chart-head"><div><h2>${persona==="auditor"?"Evidence activity":"Workspace overview"}</h2><p>Illustrative demo series · ${esc(r.org)}</p></div><button class="chart-menu" aria-label="Chart information">···</button></div><div class="chart-area"><span>${persona==="auditor"?"≋":"◈"}</span><strong>${persona==="auditor"?"Synthetic evidence sample":"Illustrative demo series"}</strong><small>Indicative · local fixture · no live valuation</small></div>${source("Role-scoped demo fixture · no external data source")}</div><div class="bottom-grid"><div class="panel list-panel"><div class="panel-heading"><div><div class="eyebrow">${persona==="auditor"?"AUDIT WORKPAPERS":"WORKFLOW QUEUE"}</div><h2>${esc(workLabel)} <span class="count-pill">${work.length.toString().padStart(2,"0")}</span></h2></div><button class="inline-link" data-nav="${persona==="auditor"?"Audit center":"Tasks & approvals"}">View all →</button></div>${work.slice(0,2).map(x=>`<div class="compact-record"><span class="record-mark">▣</span><div class="record-body"><strong>${esc(x.title)}</strong><small>${esc(x.detail)}</small></div><span class="compact-value">${esc(x.amount)}</span><button class="mini-action" data-action="record" data-id="${esc(x.id)}" aria-label="View ${esc(x.id)}">↗</button></div>`).join("")}<div class="panel-foot"><span>${persona==="auditor"?"Read-only evidence scope":"Synthetic workflow · no real approval"}</span><button class="text-button" data-nav="${persona==="auditor"?"Audit center":"Tasks & approvals"}">Open queue →</button></div></div><div class="panel list-panel"><div class="panel-heading"><div><div class="eyebrow">${persona==="auditor"?"CUSTODY EVIDENCE":"SETTLEMENT MONITOR"}</div><h2>${persona==="auditor"?"Evidence reference":"In flight"}</h2></div><button class="inline-link" data-nav="${persona==="auditor"?"Audit center":"Settlement monitor"}">View details →</button></div><div class="settlement-flow"><div class="flow-top"><span class="flow-id">${esc(gold.id)}</span>${badge(gold.status,gold.status.toLowerCase())}</div><strong>${esc(gold.asset)}</strong><small>${esc(gold.counterparty)} · ${esc(gold.cash)}</small><div class="flow-steps"><div class="done"><i>✓</i><span>Record logged</span></div><div class="done"><i>✓</i><span>Scope checked</span></div><div class="waiting"><i>3</i><span>Evidence review</span></div><div><i>4</i><span>Reconcile</span></div></div><div class="panel-foot"><span>${settlementScope}</span>${linkRecord(gold.id)}</div></div></div></div></div><aside class="right-stack"><div class="panel risk-panel"><div class="panel-heading"><div><div class="eyebrow">${persona==="auditor"?"CONTROL EVIDENCE":"CONTROL POSTURE"}</div><h2>${persona==="auditor"?"Review scope":"Risk & controls"}</h2></div>${badge("Demo only","info")}</div><div class="risk-meter"><div><span>${persona==="auditor"?"Evidence completeness":"Sample limit utilization"}</span><strong>${persona==="auditor"?"4 refs":"68%"}</strong></div><div class="meter"><i style="width:68%"></i></div><small>Illustrative only · no live policy engine</small></div><div class="risk-lines"><div><span>Counterparty / assignment scope</span><strong>${esc(r.unit.split("·")[0].trim())}</strong></div><div><span>Settlement events</span><strong>${persona==="auditor"?"Read-only":"Sample only"}</strong></div><div><span>Current environment</span><strong>Sandbox</strong></div></div><button class="text-button" data-action="about">Review prototype scope →</button></div><div class="panel alert-panel"><div class="panel-heading"><div><div class="eyebrow">TODAY'S ATTENTION</div><h2>${persona==="auditor"?"Evidence notices":"Operational alerts"}</h2></div><span class="alert-count">${persona==="auditor"?"1":"2"}</span></div><div class="alert-item"><span class="alert-mark amber">!</span><div><strong>${persona==="auditor"?"Evidence link is synthetic":"Vault evidence pending"}</strong><small>${persona==="auditor"?"Audit assignment · local fixture":"STL-2025-03812 · Crown Custody"}</small></div><span class="alert-time">09:32</span></div><div class="alert-item"><span class="alert-mark red">!</span><div><strong>Insurance record needs review</strong><small>Crown Custody · sample case</small></div><span class="alert-time">08:55</span></div><button class="text-button" data-nav="${persona==="auditor"?"Audit center":"Compliance"}">Open register →</button></div><div class="panel coverage-card"><span class="coverage-icon">◌</span><div><strong>Phase 1 sandbox workspace</strong><p>${esc(r.permissions)} · synthetic sample scope only. No live integrations.</p><button class="inline-link" data-action="about">Prototype scope ↗</button></div></div></aside></div>${source(`Scoped demo fixture · ${r.org} · USD · values indicative`)}`
}
function approvalsView(){const roleTasks=scopedApprovals(),rows=roleTasks.map(x=>`<tr><td><button class="table-primary" data-action="record" data-id="${x.id}">${esc(x.title)}</button><small>${x.id}</small></td><td>${esc(x.detail)}<small>Requester: ${esc(x.requester)}</small></td><td>${esc(x.amount)}</td><td>${badge(x.risk,x.risk.toLowerCase())}</td><td>${badge(x.status,"pending")}<small>${x.age}</small></td><td>${linkRecord(x.id)}</td></tr>`).join("");const ro=["auditor","regulator"].includes(persona);return `${heading("GOVERNANCE · WORKFLOW","Tasks & approvals","A traceable maker-checker queue. Selecting a record never authorizes a financial action.",ro?badge("Read-only role","info"):btn("New demo request","rfq","primary","＋"))}<div class="notice-banner"><span>◇</span><div><strong>Sandbox queue · not approval authority</strong><small>For interface testing only. No transaction is authorized, funded or settled.</small></div></div><div class="filter-row"><div class="tabs"><button class="tab active" data-filter="All">Pending <span>${roleTasks.length}</span></button><button class="tab" data-filter="Completed">Completed</button></div><button class="button button-secondary" data-action="filters">☷ Filters</button></div><div class="panel table-panel">${table(["TASK / REFERENCE","REQUEST DETAILS","VALUE","RISK","STATUS",""],rows)}<div class="table-footer"><span>${roleTasks.length} synthetic role-scoped task${roleTasks.length===1?"":"s"} · updated just now</span><span>Two-person review shown for demonstration only</span></div></div><div class="approval-footnotes">${[["01","Requester","Person who raised the task."],["02","Approver","Independent review role."],["03","Evidence","Linked source record and audit trail."],["04","Finality","Never represented as real settlement."]].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join("")}</div>${source("Workflow records · synthetic · local demo only")}`}
function goldView(){const data=scopeBars(),quoteButton=["operator","commercial","bullion"].includes(persona)?btn("Request a quote","rfq","primary","＋"):badge("Read-only scope","info"),rows=data.map(b=>`<tr><td><button class="table-primary mono" data-action="record" data-id="${b.id}">${b.id}</button><small>${b.serial}</small></td><td>${b.refinery}<small>Origin · ${b.origin}</small></td><td class="numeric">${b.gross.toFixed(3)} kg<small>${b.fine.toFixed(3)} fine kg</small></td><td>${b.purity}</td><td>${b.vault}<small>Custodian · Crown Custody</small></td><td>${badge(b.status,b.status.toLowerCase())}</td><td>${linkRecord(b.id)}</td></tr>`).join("");return `${heading("MARKETS · ALLOCATED ASSET REGISTER","Gold & bullion","Allocated bars, ownership, custody and sourcing evidence · synthetic sample records only.",quoteButton)}<div class="asset-overview"><div><span>REGISTERED SAMPLE BARS</span><strong>${persona==="commercial"?"312":"1,248"}</strong><small>Scope-filtered synthetic inventory</small></div><div><span>FINE WEIGHT</span><strong>486,204 <small>oz</small></strong><small>Valuation status · indicative</small></div><div><span>ALLOCATED VALUE</span><strong>$1.56B</strong><small>Reference · simulated</small></div><div><span>RECORD QUALITY</span><strong class="quality-value">98.4%</strong><small>Evidence completeness · sample</small></div></div><div class="filter-row"><div class="tabs"><button class="tab active" data-filter="All">All bars</button><button class="tab" data-filter="Available">Available</button><button class="tab" data-filter="Reserved">Reserved</button><button class="tab" data-filter="Pledged">Pledged</button><button class="tab" data-filter="Blocked">Blocked</button></div><button class="button button-secondary" data-action="filters">⌕ Search & filter</button></div><div class="panel table-panel" id="barsTable">${table(["BAR ID / SERIAL","REFINERY / ORIGIN","GROSS WEIGHT","FINENESS","VAULT / CUSTODIAN","STATUS",""],rows)}<div class="table-footer"><span>Sample record count is fictional</span><span>Role-specific fixture scope</span></div></div><div class="callout-grid"><div class="callout"><span class="callout-icon">◇</span><div><strong>Provenance & sourcing</strong><small>Assay, refinery, origin and sourcing records are sample metadata.</small></div></div><div class="callout"><span class="callout-icon">⬡</span><div><strong>Custody & encumbrance</strong><small>Available, reserved and pledged states are fictional, not legal title.</small></div></div></div>${source("Indicative simulated valuation · USD per fine troy ounce")}`}
function bondsView(){const scopedBonds=persona==="commercial"?bonds.filter(b=>b.currency==="USD"):persona==="bullion"?bonds.filter(b=>b.issuer==="Republic of Norland"):bonds,rows=scopedBonds.map(b=>`<tr><td><button class="table-primary" data-action="record" data-id="${b.isin}">${esc(b.name)}</button><small class="mono">${b.isin}</small></td><td>${esc(b.issuer)}<small>Rating · ${b.rating}</small></td><td>${b.currency}<small>${b.coupon} coupon</small></td><td>${b.maturity}</td><td>${b.yield}<small>Duration · ${b.duration}</small></td><td class="numeric">${money(b.value,b.currency)}<small>Value · indicative</small></td><td>${badge("Eligible","normal")}</td></tr>`).join("");return `${heading("RESERVES · FIXED INCOME","Government bonds","Reserve-quality sovereign and public-sector holdings · sample positions only.",btn("Export holdings","export"))}<div class="asset-overview"><div><span>MARKET VALUE</span><strong>$876M</strong><small>USD equivalent · indicative</small></div><div><span>ACTIVE POSITIONS</span><strong>12</strong><small>3 currencies · 4 issuers</small></div><div><span>WEIGHTED DURATION</span><strong>4.2 <small>yrs</small></strong><small>Indicative sensitivity</small></div><div><span>NEXT MATURITY</span><strong>15 Jun 2030</strong><small>Norland · illustrative</small></div></div><div class="filter-row"><div class="tabs"><button class="tab active" data-filter="All">All holdings</button><button class="tab" data-filter="USD">USD</button><button class="tab" data-filter="EUR">EUR</button></div><span class="indicative-pill">◉ Indicative pricing · not executable</span></div><div class="panel table-panel">${table(["INSTRUMENT","ISSUER / RATING","CURRENCY / COUPON","MATURITY","YIELD / DURATION","MARKET VALUE","COLLATERAL"],rows)}<div class="table-footer"><span>3 representative records from 12 synthetic holdings</span><span>Simulated pricing · 10:30 UTC</span></div></div>${source("Synthetic instrument master · native currency display")}`}
function accountsView(){const list=persona==="commercial"?accounts.filter(x=>x.currency==="USD"):persona==="settlement"?accounts.filter(x=>x.currency!=="CHF"):persona==="custodian"?[]:accounts.filter(x=>x.currency==="USD"||persona==="regulator"),rows=list.map(a=>`<tr><td><button class="table-primary" data-action="record" data-id="${a.id}">${esc(a.name)}</button><small class="mono">${a.id}</small></td><td>${a.currency}</td><td class="numeric">${money(a.balance,a.currency)}<small>Settled balance · synthetic</small></td><td class="numeric">${money(a.available,a.currency)}<small>Available · indicative</small></td><td class="numeric">${money(a.reserved,a.currency)}</td><td>${badge(a.status,"normal")}</td><td>${linkRecord(a.id)}</td></tr>`).join("");return `${heading("RESERVES · CASH","Settlement accounts","Currency balances and reservations in a simulated ledger.",btn("Create transfer","blocked"))}<div class="notice-banner"><span>◇</span><div><strong>Sandbox accounts · transfer controls unavailable</strong><small>Fictional balances; no payment rail or production account connection.</small></div></div><div class="asset-overview"><div><span>AVAILABLE LIQUIDITY</span><strong>$2.45B</strong><small>Equivalent · sample accounts</small></div><div><span>RESERVED</span><strong>$250M</strong><small>Illustrative only</small></div><div><span>RECONCILIATION</span><strong class="quality-value">100%</strong><small>Fixture · not verified</small></div><div><span>ACCOUNT STATUS</span><strong>${list.length} active</strong><small>Synthetic accounts</small></div></div><div class="panel table-panel">${table(["ACCOUNT","CURRENCY","SETTLED BALANCE","AVAILABLE","RESERVED","STATUS",""],rows)}</div>${source("Simulated ledger · fictional balances · local preview")}`}
function settlementView(){const scopedSettlements=persona==="custodian"?settlements.filter(x=>x.asset.toLowerCase().includes("vault")||x.asset.toLowerCase().includes("gold")):persona==="commercial"?settlements.filter(x=>x.counterparty==="Meridian Commercial Bank"):persona==="bullion"?settlements.filter(x=>x.counterparty==="Auric Bullion Bank"):settlements,rows=scopedSettlements.map(x=>`<tr><td><button class="table-primary mono" data-action="record" data-id="${x.id}">${x.id}</button><small>${x.trade}</small></td><td>${esc(x.counterparty)}</td><td>${esc(x.asset)}<small>Cash · ${esc(x.cash)}</small></td><td>${esc(x.date)}</td><td>${badge(x.cashState,x.cashState==="Reserved"?"pending":"normal")}<small>${esc(x.assetState)}</small></td><td>${badge(x.status,x.status.toLowerCase())}</td><td>${linkRecord(x.id)}</td></tr>`).join("");return `${heading("CUSTODY · SETTLEMENT","Settlement monitor","Illustrative cash and asset legs through simulated delivery states.",btn("Record an exception","blocked"))}<div class="settlement-kpis">${[["IN FLIGHT","01","Sample transactions"],["RECONCILED TODAY","06","Fictional status history"],["EXCEPTIONS","02","Evidence review"],["SUCCESS RATE","98.2%","Illustrative only"]].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join("")}</div><div class="settlement-stage panel"><div class="stage-header"><div><div class="eyebrow">DELIVERY-VERSUS-PAYMENT LIFECYCLE</div><h2>Illustrative progress</h2></div>${badge("Simulated states","info")}</div><div class="timeline"><div class="complete"><i>✓</i><span>Trade agreed</span></div><div class="complete"><i>✓</i><span>Compliance cleared</span></div><div class="complete"><i>✓</i><span>Cash reserved</span></div><div class="current"><i>4</i><span>Asset confirmation</span></div><div><i>5</i><span>DvP complete</span></div><div><i>6</i><span>Reconciled</span></div></div><p class="stage-note">Sample records only; no money or assets move here.</p></div><div class="panel table-panel">${table(["SETTLEMENT / TRADE","COUNTERPARTY","ASSET / CASH LEG","VALUE DATE","LEG STATUS","OVERALL",""],rows)}</div>${source("No RTGS, SWIFT, CSD or custodian integration")}`}
function custodyView(){const rows=scopeBars().map(b=>`<tr><td>${esc(b.vault)}<small>${b.id}</small></td><td>${esc(b.owner)}</td><td>Crown Custody<small>Custodian · sample</small></td><td>${b.fine.toFixed(3)} kg</td><td>${badge(b.status,b.status.toLowerCase())}</td><td>${badge("Verified · sample","normal")}</td><td>${linkRecord(b.id,"Evidence")}</td></tr>`).join("");return `${heading("CUSTODY · STORAGE","Custody & vaults","Sample vault directory, ownership references and physical inspection records.",btn("Request inspection","blocked"))}<div class="vault-cards">${[["Zurich Vault 02","Switzerland","824","321,480 oz","14 Feb 2025"],["London Vault 01","United Kingdom","306","118,204 oz","03 Mar 2025"]].map(v=>`<div class="vault-card"><div class="vault-top"><span class="vault-symbol">⬡</span>${badge("Operational · sample","normal")}</div><strong>${v[0]}</strong><small>Crown Custody Services · ${v[1]}</small><div class="vault-metrics"><div><span>Bars</span><b>${v[2]}</b></div><div><span>Fine weight</span><b>${v[3]}</b></div><div><span>Inspection</span><b>${v[4]}</b></div></div></div>`).join("")}<div class="vault-card vault-card-add"><span class="vault-symbol">⌕</span><strong>Directory scope</strong><small>Sample sites shown to ${esc(roles[persona].title)}.</small><button class="inline-link" data-action="about">Data boundaries ↗</button></div></div><div class="panel table-panel"><div class="section-title"><h2>Custody register</h2><span class="table-caption">Sample bar-level evidence</span></div>${table(["VAULT / SAMPLE BAR","LEGAL OWNER","CUSTODIAN","FINE WEIGHT","ENCUMBRANCE","INSPECTION",""],rows)}</div><div class="notice-banner"><span>!</span><div><strong>Proof-of-reserves is not attested</strong><small>Inspection dates and custodian confirmations are fictional metadata.</small></div></div>${source("Synthetic vault and ownership records · no custodian integration")}`}
function riskView(){return `${heading("RISK · CONTROL FRAMEWORK","Risk & limits","Illustrative policy utilization · not a live risk engine.",btn("View limit policy","policy"))}<div class="notice-banner"><span>◇</span><div><strong>Indicative risk metrics · synthetic fixture</strong><small>No orders are evaluated or blocked by this interface.</small></div></div><div class="stat-grid">${stat("Portfolio limit use","68%","Review threshold · 82%","⌁")}${stat("Gold price risk","$42.8M","Indicative shock","◈","gold")}${stat("Counterparty exposure","$412M","Auric Bullion Bank","▧","violet")}${stat("Liquidity buffer","94%","Illustrative minimum","◉","green")}</div><div class="risk-content-grid"><div class="panel risk-policy"><div class="panel-heading"><div><div class="eyebrow">POLICY CONTROLS</div><h2>Limit utilization</h2></div>${badge("1 review","elevated")}</div>${[["Gold concentration","68%","82%"],["Counterparty · Auric","71%","85%"],["Settlement intraday","42%","75%"],["Vault single-site","54%","70%"]].map(x=>`<div class="limit-row"><div><strong>${x[0]}</strong><small>Indicative sample policy</small></div><strong>${x[1]}</strong><div class="meter"><i style="width:${x[1]}"></i></div><small>Review at ${x[2]}</small></div>`).join("")}</div><div class="panel stress-panel"><div class="eyebrow">STRESS SNAPSHOT</div><h2>Gold repricing shock</h2><p>Illustrative scenario</p><div class="stress-shock">−8.0%</div><div class="stress-row"><span>Portfolio impact</span><strong>−$702M</strong></div><div class="stress-row"><span>Liquidity after shock</span><strong>$1.75B</strong></div>${source("Static example · not a risk calculation")}</div></div>${source("Synthetic risk fixture · no policy evaluation")}`}
function complianceView(){const scopedCases=persona==="commercial"?cases.filter(x=>x.entity==="Meridian Commercial Bank"):persona==="bullion"?cases.filter(x=>x.entity==="Auric Bullion Bank"):persona==="custodian"?cases.filter(x=>x.entity==="Crown Custody Services"):cases,rows=scopedCases.map(x=>`<tr><td><button class="table-primary" data-action="record" data-id="${x.id}">${esc(x.title)}</button><small>${x.id} · ${esc(x.category)}</small></td><td>${esc(x.entity)}</td><td>${badge(x.severity,x.severity.toLowerCase())}</td><td>${esc(x.due)}</td><td>${badge(x.status,"pending")}</td><td>${linkRecord(x.id)}</td></tr>`).join("");return `${heading("RISK · COMPLIANCE","Compliance dashboard","KYC, sourcing and custody documentation review across synthetic counterparties.",btn("New review case","blocked"))}<div class="stat-grid">${stat("Open cases","03","Sample institutions","◇")}${stat("KYC / KYB current","96.2%","Synthetic status","▣","green")}${stat("Sourcing evidence","92.8%","Gold provenance sample","◈","gold")}${stat("Document alerts","02","Expiry and refresh","▤","violet")}</div><div class="filter-row"><div class="tabs"><button class="tab active" data-filter="All">All cases</button><button class="tab" data-filter="Elevated">Elevated</button><button class="tab" data-filter="Review">Review</button></div></div><div class="panel table-panel">${table(["CASE / CATEGORY","COUNTERPARTY","SEVERITY","DUE","STATUS",""],rows)}</div><div class="compliance-callout"><span>◇</span><div><strong>Compliance states are not screening results</strong><small>No sanctions, KYC, beneficial ownership or source-of-funds provider is connected.</small></div></div>${source("Fictional compliance records · no external screening")}`}
function auditView(){const rows=events.map(x=>`<tr><td class="mono">${x.time} UTC</td><td>${esc(x.actor)}<small>${esc(roles[persona].org)}</small></td><td>${esc(x.event)}<small>${esc(x.detail)}</small></td><td class="mono">${esc(x.target)}</td><td>${badge(x.kind,x.kind.toLowerCase())}</td><td>${linkRecord(x.target,"Evidence")}</td></tr>`).join("");return `${heading("GOVERNANCE · EVIDENCE","Audit center","Synthetic event history and evidence references · read-only records.",btn("Export event log","export"))}<div class="audit-summary"><div><span>EVENTS IN SAMPLE LOG</span><strong>1,842</strong><small>Representative fixture count</small></div><div><span>LAST EVIDENCE CHECK</span><strong>10:42 UTC</strong><small>05 Oct 2026 · synthetic</small></div><div><span>TAMPER STATUS</span><strong class="quality-value">DEMO ONLY</strong><small>No cryptographic attestation</small></div></div><div class="notice-banner"><span>≋</span><div><strong>Demonstration event log — not immutable</strong><small>Sample events illustrate traceability only; there is no durable audit store or cryptographic verification.</small></div></div><div class="filter-row"><div class="tabs"><button class="tab active" data-filter="All">All events</button><button class="tab" data-filter="Access">Access</button><button class="tab" data-filter="Draft">Drafts</button><button class="tab" data-filter="Evidence">Evidence</button><button class="tab" data-filter="Exception">Exceptions</button></div></div><div class="panel table-panel">${table(["TIME","ACTOR / INSTITUTION","EVENT / DESCRIPTION","RECORD","TYPE",""],rows)}<div class="table-footer"><span>4 entries · total count synthetic</span><span>In-memory fixture · UTC</span></div></div>${source("Sample event data · no durable logging")}`}
function reportsView(){const all=[["Reserve briefing","Executive allocation & liquidity snapshot","▦"],["Gold holdings register","Allocated bars, custody and provenance","◈"],["Bond portfolio","Sovereign holdings & maturity summary","▤"],["Settlement exceptions","Illustrative cash and asset status","◷"],["Compliance summary","Sample counterparty review cases","◇"],["Audit evidence index","Example event references and history","≋"]];return `${heading("GOVERNANCE · REPORTING","Reports","Sample briefing exports and holdings summaries for prototype review.",btn("Prepare demo briefing","export","primary","↓"))}<div class="report-grid">${all.map(x=>`<article class="report-card"><div class="report-icon">${x[2]}</div><span class="report-format">DEMO · SYNTHETIC</span><h2>${esc(x[0])}</h2><p>${esc(x[1])}</p><small>As of 05 Oct 2026 · indicative</small><button class="inline-link" data-action="export">Preview sample ↗</button></article>`).join("")}</div><div class="notice-banner"><span>!</span><div><strong>No real report file is produced</strong><small>No regulator delivery, data export or scheduled reporting service exists.</small></div></div>${source("Report descriptions are fixtures; no export backend")}`}
function roadmapView(){const items=[["Auctions & issuance","Programmes, bids, allocations and approvals",2],["ISO 20022 & integrations","Custodian, payment and market-data connections",2],["Accounting & general ledger","Journals, statements, valuation and close",2],["Production & tokenized assets","Approved rails, programmable collateral and network settlement",3]];return `${heading("PRODUCT PLAN · NOT AVAILABLE","Phase 2 roadmap","Remaining roadmap scope. The FX, repo & collateral and gold financing sandbox workspaces are implemented for dealing personas; these workflows are not.")}<div class="roadmap-grid">${items.map(x=>`<div class="roadmap-card"><span>PHASE ${x[2]}</span><h2>${esc(x[0])}</h2><p>${esc(x[1])}</p><small>Not implemented · no live backend</small></div>`).join("")}</div>${source("Roadmap preview only · not a delivery commitment")}`}
function fxView(){const s=scopedPhase2().fx,rows=s.map(x=>`<tr><td><strong>${esc(x.pair)}</strong><small>${esc(x.unit)}</small></td><td class="numeric">${x.unit.includes("oz")?x.bid.toFixed(2):x.bid.toFixed(4)}</td><td class="numeric">${x.unit.includes("oz")?x.ask.toFixed(2):x.ask.toFixed(4)}</td><td>${x.forwardPts}</td><td>${esc(x.tenor)}</td><td>${badge(x.status,"info")}</td></tr>`).join("");return `${heading("MARKETS · MONEY DESK","FX & money markets","Indicative FX and money-market reference data · synthetic sample rates only.",btn("Draft FX trade","blocked"))}<div class="notice-banner"><span>⇄</span><div><strong>Indicative rates · not executable</strong><small>No pricing provider, dealing platform or settlement rail is connected. Rates are static demo values.</small></div></div><div class="stat-grid">${stat("XAU/USD spot","3,280.90 / 3,281.60","Loco London · synthetic","◈","gold")}${stat("EUR/USD 1M","−12.4 pts","Forward points · sample","⇄")}${stat("Open FX positions","00","No live dealing · fixture","▤","violet")}${stat("Liquidity placements","02","Illustrative money-market lines","▧","green")}</div><div class="panel table-panel">${table(["PAIR / UNIT","BID","ASK","FWD POINTS","TENOR","STATUS"],rows)}</div><div class="callout-grid"><div class="callout"><span class="callout-icon">▧</span><div><strong>Money-market placements</strong><small>Call and term placement screens are roadmap-only; nothing is placed or rolled here.</small></div></div><div class="callout"><span class="callout-icon">◇</span><div><strong>Forex exposure is not computed</strong><small>No position keeping, revaluation or P&L engine exists in this prototype.</small></div></div></div>${source("Static synthetic rate board · 10:30 UTC fixture")}`}
function repoView(){const s=scopedPhase2().repo,rows=s.map(x=>`<tr><td><button class="table-primary mono" data-action="record" data-id="${x.id}">${x.id}</button><small>${esc(x.side)}</small></td><td>${esc(x.collateral)}<small class="mono">ISIN / bar · ${esc(x.isin)}</small></td><td class="numeric">${esc(x.cash)}</td><td>${x.haircut}</td><td>${x.rate}</td><td>${esc(x.maturity)}</td><td>${badge(x.status,x.status==="Settled"?"normal":"pending")}</td></tr>`).join("");return `${heading("MARKETS · FUNDING & COLLATERAL","Repo & collateral","Bilateral repo, reverse repo and collateral eligibility · synthetic sample trades only.",btn("Initiate repo","blocked"))}<div class="notice-banner"><span>⌗</span><div><strong>Sample funding trades · no market or triparty agent</strong><small>Haircuts, rates and margin states are fictional; no collateral is pledged or recalled.</small></div></div><div class="settlement-kpis">${[["OPEN SAMPLE TRADES","03","Repo and reverse repo"],["OUTSTANDING CASH","$253.9M","Illustrative funding volume"],["AVERAGE HAIRCUT","3.2%","Sample policy levels"],["NEXT MATURITY","06 Oct 2026","Overnight trade · fixture"]].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join("")}</div><div class="panel table-panel">${table(["TRADE / SIDE","COLLATERAL","CASH LEG","HAIRCUT","RATE","MATURITY","STATUS"],rows)}</div><div class="callout-grid"><div class="callout"><span class="callout-icon">◈</span><div><strong>Eligible collateral · sample policy</strong><small>Allocated gold and sovereign bonds are shown as eligible; haircuts are illustrative only.</small></div></div><div class="callout"><span class="callout-icon">⌗</span><div><strong>No margin engine</strong><small>Margin calls, substitution and collateral recalculation are not simulated.</small></div></div></div>${source("Synthetic repo fixture · no market data or triparty integration")}`}
function financingView(){const s=scopedPhase2().fin,rows=s.map(x=>`<tr><td><button class="table-primary mono" data-action="record" data-id="${x.id}">${x.id}</button><small>${esc(x.type)}</small></td><td>${esc(x.counterparty)}</td><td>${esc(x.quantity)}</td><td>${x.rate}</td><td>${esc(x.tenor)}</td><td class="numeric">${esc(x.value)}</td><td>${badge(x.status,x.status==="Active"?"normal":"info")}</td></tr>`).join("");return `${heading("MARKETS · GOLD FINANCING","Gold financing","Gold loans and leases against allocated metal · synthetic sample facilities only.",btn("New facility","blocked"))}<div class="notice-banner"><span>◆</span><div><strong>Financing records are illustrative</strong><small>No interest accrual, rollover or title transfer is computed; metal never moves in this prototype.</small></div></div><div class="stat-grid">${stat("Open facilities","03","Sample loans and leases","◆")}${stat("Metal financed","19,500 oz","Allocated · synthetic","◈","gold")}${stat("Average lease rate","1.99% p.a.","Illustrative sample","⌗","violet")}${stat("Facility value","$64.0M","Indicative · not funded","▧","green")}</div><div class="panel table-panel">${table(["FACILITY / TYPE","COUNTERPARTY","QUANTITY","RATE","TENOR","VALUE","STATUS"],rows)}</div><div class="callout-grid"><div class="callout"><span class="callout-icon">⬡</span><div><strong>Custody unchanged</strong><small>Leased metal remains in the sample vault register; no allocation change is recorded.</small></div></div><div class="callout"><span class="callout-icon">◇</span><div><strong>No accounting postings</strong><small>Accruals, journals and GL integration are Phase 2 roadmap items, not implemented.</small></div></div></div>${source("Synthetic financing fixture · rates indicative only")}`}
const views={"Dashboard":dashboard,"Tasks & approvals":approvalsView,"Gold & bullion":goldView,"Government bonds":bondsView,"Settlement accounts":accountsView,"Settlement monitor":settlementView,"Custody & vaults":custodyView,"Risk & limits":riskView,"Compliance":complianceView,"Audit center":auditView,"Reports":reportsView,"FX & money markets":fxView,"Repo & collateral":repoView,"Gold financing":financingView,"Reserve overview":dashboard,"Phase 2 workspaces":roadmapView};
function render(){renderNav();renderContext();$("#pageContent").innerHTML=(views[page]||dashboard)();$("#currentCrumb").textContent=page;document.title=`${page} · Veritas Gold Sandbox`}
function showAbout(){dialog(`<div class="dialog-head"><button class="dialog-close" data-action="close">×</button><div class="eyebrow">PRODUCT REVIEW · PHASE 1</div><h2 id="dialogTitle">Veritas Gold sandbox prototype</h2><p>A clickable interface based on the supplied central-bank and participant-persona specifications.</p></div><div class="scope-list"><div><span>✓</span><p><strong>Prototype surfaces</strong><br>Phase 1 persona navigation, gold/bar registry and RFQ draft, bonds, approvals, custody, settlement, compliance, risk and audit.</p></div><div><span>!</span><p><strong>Synthetic data only</strong><br>All institutions, identities, bars, balances and prices are fictional and illustrative.</p></div><div><span>×</span><p><strong>Not implemented</strong><br>No login, backend, authorization, production mode, ledger, external integration, transaction approval or actual settlement.</p></div></div><div class="dialog-actions">${btn("Understood","close","primary")}</div>`)}
function dialog(html){$("#dialogContent").innerHTML=html;$("#appDialog").showModal()}
function switchDialog(){const choices=Object.entries(roleLabels).map(([id,label])=>`<button class="persona-option ${id===persona?"selected":""}" data-role="${id}"><span class="avatar">${roles[id].name.replaceAll(".","").split(/\s+/).map(x=>x[0]).join("")}</span><span><strong>${label}</strong><small>${esc(roles[id].org)}</small></span>${id===persona?`<span class="selected-check">✓</span>`:""}</button>`).join("");dialog(`<div class="dialog-head"><button class="dialog-close" data-action="close">×</button><div class="eyebrow">PHASE 1 · ROLE PREVIEW</div><h2 id="dialogTitle">Switch demo persona</h2><p>Preview interface scope for a Phase 1 participant. This is not authentication or access control.</p></div><div class="persona-list">${choices}</div><div class="dialog-footnote">No identity, permissions, counterparties or live data are loaded.</div>`)}
function switchPersona(next){const before=roles[persona],after=roles[next];persona=next;page=alias[after.nav[0]]||after.nav[0];render();dialog(`<div class="dialog-head"><div class="dialog-mark">⇄</div><button class="dialog-close" data-action="close">×</button><div class="eyebrow">DEMO PERSONA SWITCH</div><h2 id="dialogTitle">Workspace context updated</h2><p>Menus and synthetic sample scope changed for this preview. This is not authentication or access control.</p></div><div class="switch-audit"><div><span>PREVIOUS PERSONA</span><strong>${esc(before.title)} · ${esc(before.org)}</strong></div><div class="switch-arrow">↓</div><div><span>NEW PERSONA</span><strong>${esc(after.title)} · ${esc(after.org)}</strong></div><div><span>PERMISSIONS LOADED · DEMO ONLY</span><strong>${esc(after.permissions)}</strong></div><div><span>ENVIRONMENT · REASON</span><strong>Sandbox · user-selected preview</strong></div><div><span>SWITCH RECORDED</span><strong>${new Date().toLocaleString("en-GB",{hour12:false})}</strong></div></div><div class="dialog-actions">${btn("Continue in workspace","close","primary")}</div>`)}
function record(id){const b=bars.find(x=>x.id===id),a=approvals.find(x=>x.id===id),s=settlements.find(x=>x.id===id),bond=bonds.find(x=>x.isin===id),c=cases.find(x=>x.id===id),acct=accounts.find(x=>x.id===id),r=repoTrades.find(x=>x.id===id),f=goldFinancing.find(x=>x.id===id);let title=id,fields=[];if(b){title=`Allocated gold bar · ${id}`;fields=[["Serial number",b.serial],["Refinery / origin",`${b.refinery} · ${b.origin}`],["Gross / fine weight",`${b.gross.toFixed(3)} kg · ${b.fine.toFixed(3)} fine kg`],["Purity",b.purity],["Vault / custodian",`${b.vault} · Crown Custody Services`],["Legal owner",b.owner],["Encumbrance status",b.status],["Assay evidence",b.assay]]}else if(a){title=a.title;fields=[["Task reference",a.id],["Request",a.detail],["Value",a.amount],["Requester",a.requester],["Risk / status",`${a.risk} · ${a.status}`],["Evidence",a.evidence],["Approval policy","Simulated · not executable"]]}else if(s){title=`Settlement · ${s.id}`;fields=[["Trade reference",s.trade],["Counterparty",s.counterparty],["Asset leg",s.asset],["Cash leg",s.cash],["Cash state",s.cashState],["Asset state",s.assetState],["Final state",s.status],["Settlement rail","None connected · synthetic"]]}else if(bond){title=bond.name;fields=[["ISIN",bond.isin],["Issuer / rating",`${bond.issuer} · ${bond.rating}`],["Currency / coupon",`${bond.currency} · ${bond.coupon}`],["Maturity / yield",`${bond.maturity} · ${bond.yield}`],["Duration",bond.duration],["Indicative value",money(bond.value,bond.currency)],["Data source","Synthetic market-data fixture"]]}else if(c){title=c.title;fields=[["Case reference",c.id],["Entity",c.entity],["Category",c.category],["Severity",c.severity],["Due",c.due],["Status",c.status],["Evidence","Synthetic record · review only"]]}else if(acct){title=acct.name;fields=[["Account reference",acct.id],["Currency",acct.currency],["Settled balance",money(acct.balance,acct.currency)],["Available",money(acct.available,acct.currency)],["Reserved",money(acct.reserved,acct.currency)],["Status",acct.status],["Source","Synthetic fixture · no payment rail"]]}else if(r){title=`Repo trade · ${id}`;fields=[["Trade reference",r.id],["Side",r.side],["Collateral",r.collateral],["ISIN / bar",r.isin],["Cash leg",r.cash],["Haircut / rate",`${r.haircut} · ${r.rate}`],["Maturity",r.maturity],["Status",r.status],["Market data","None · synthetic fixture"]]}else if(f){title=`Gold financing · ${id}`;fields=[["Facility reference",f.id],["Type",f.type],["Counterparty",f.counterparty],["Quantity",f.quantity],["Rate",f.rate],["Tenor",f.tenor],["Indicative value",f.value],["Status",f.status],["Accounting","No postings · synthetic"]]}else fields=[["Reference",id],["Source","Synthetic demo fixture"],["Environment","Sandbox · no live record"]];dialog(`<div class="dialog-head"><button class="dialog-close" data-action="close">×</button><div class="eyebrow">SYNTHETIC RECORD · SANDBOX</div><h2 id="dialogTitle">${esc(title)}</h2><p>Evidence view only. Not a statement of title, funds, approval or settlement.</p></div><div class="record-detail-grid">${fields.map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join("")}</div><div class="dialog-footnote">Viewed by ${esc(roles[persona].name)} · ${new Date().toLocaleString("en-GB")} · local preview only</div>`)}
function rfq(){if(["auditor","regulator","custodian","settlement","governor"].includes(persona)){toast("The active demo persona is read-only for quote requests.");return}dialog(`<div class="dialog-head"><button class="dialog-close" data-action="close">×</button><div class="eyebrow">SANDBOX · NO ORDER TRANSMITTED</div><h2 id="dialogTitle">Draft gold RFQ</h2><p>Local demonstration request only. No counterparty contact or fund reservation.</p></div><form id="rfqForm" class="form-grid"><label>Institution<input value="${esc(roles[persona].org)}" disabled></label><label>Counterparty<select><option>Auric Bullion Bank</option><option>Meridian Commercial Bank</option></select></label><label>Side<select><option>Buy allocated gold</option><option>Sell allocated gold</option></select></label><label>Quantity · fine troy oz<input name="quantity" type="number" min="100" max="10000" step="100" value="2500" required></label><label>Reference price<input value="$3,281.25 / oz · indicative" disabled></label><label>Settlement date<input type="date" value="2026-10-07"></label><div class="form-wide notice-inline">Save only triggers a local demo confirmation. No execution, approval or settlement occurs.</div><div class="dialog-actions form-wide"><button type="button" class="button button-secondary" data-action="close">Cancel</button><button type="submit" class="button button-primary">Save demo draft</button></div></form>`);$("#rfqForm").addEventListener("submit",e=>{e.preventDefault();$("#appDialog").close();toast("RFQ demo draft noted locally. No quote was sent.","success")})}
function search(q){const box=$("#searchResults");if(!q){box.hidden=true;return}const data=[...scopeBars().map(x=>({id:x.id,title:`Gold bar · ${x.serial}`,detail:`${x.vault} · ${x.status}`,page:"Gold & bullion"})),...scopedApprovals().map(x=>({id:x.id,title:x.title,detail:x.detail,page:persona==="auditor"?"Audit center":"Tasks & approvals"})),...settlements.map(x=>({id:x.id,title:`Settlement · ${x.trade}`,detail:`${x.counterparty} · ${x.status}`,page:"Settlement monitor"})),...(persona==="commercial"?bonds.filter(x=>x.currency==="USD"):bonds).map(x=>({id:x.isin,title:x.name,detail:`${x.issuer} · ${x.currency}`,page:"Government bonds"})),...cases.filter(x=>persona==="commercial"?x.entity==="Meridian Commercial Bank":persona==="bullion"?x.entity==="Auric Bullion Bank":true).map(x=>({id:x.id,title:x.title,detail:`${x.entity} · ${x.status}`,page:"Compliance"}))].filter(x=>`${x.id} ${x.title} ${x.detail}`.toLowerCase().includes(q.toLowerCase())).slice(0,7);box.innerHTML=data.length?data.map(x=>`<button class="search-result" data-action="search-record" data-id="${x.id}" data-page="${x.page}"><span class="search-result-icon">⌕</span><span><strong>${esc(x.title)}</strong><small>${esc(x.id)} · ${esc(x.detail)}</small></span><span>↗</span></button>`).join(""):`<div class="search-empty">No matching synthetic records</div>`;box.hidden=false}
function filter(button){const value=button.dataset.filter;document.querySelectorAll(".tabs .tab").forEach(x=>x.classList.toggle("active",x===button));if(page==="Gold & bullion"){const rows=scopeBars().filter(x=>value==="All"||x.status===value).map(b=>`<tr><td><button class="table-primary mono" data-action="record" data-id="${b.id}">${b.id}</button><small>${b.serial}</small></td><td>${b.refinery}<small>Origin · ${b.origin}</small></td><td>${b.gross.toFixed(3)} kg</td><td>${b.purity}</td><td>${b.vault}</td><td>${badge(b.status,b.status.toLowerCase())}</td><td>${linkRecord(b.id)}</td></tr>`).join("");$("#barsTable tbody").innerHTML=rows||`<tr><td colspan="7" class="empty-state">No bars in this synthetic status.</td></tr>`;return}document.querySelectorAll(".table-panel tbody tr").forEach(x=>x.hidden=value!=="All"&&!x.textContent.toLowerCase().includes(value.toLowerCase()))}
document.addEventListener("click",e=>{const target=e.target.closest("[data-role]");if(target){switchPersona(target.dataset.role);return}const searchResult=e.target.closest("[data-action=search-record]");if(searchResult){const dest=alias[searchResult.dataset.page]||searchResult.dataset.page;if(!roles[persona].nav.map(x=>alias[x]||x).includes(dest)){toast("No matching record is in this persona's sample scope.");return}page=dest;render();$("#searchResults").hidden=true;$("#globalSearch").value="";record(searchResult.dataset.id);return}const nav=e.target.closest("[data-nav]");if(nav){const dest=alias[nav.dataset.nav]||nav.dataset.nav;if(!roles[persona].nav.map(x=>alias[x]||x).includes(dest)){toast("This workspace is not in the active persona's sample scope.");return}page=dest;$("#sidebar").classList.remove("sidebar-open");render();window.scrollTo({top:0,behavior:"smooth"});return}const tab=e.target.closest("[data-filter]");if(tab){filter(tab);return}const a=e.target.closest("[data-action]");if(!a)return;switch(a.dataset.action){case"switch-persona":switchDialog();break;case"close":$("#appDialog").close();break;case"dismiss":$("#toastRegion").replaceChildren();break;case"menu":$("#sidebar").classList.toggle("sidebar-open");break;case"rfq":rfq();break;case"record":record(a.dataset.id);break;case"export":toast("Sample briefing preview only; no report file or delivery created.");break;case"notifications":dialog(`<div class="dialog-head"><button class="dialog-close" data-action="close">×</button><div class="eyebrow">SANDBOX NOTIFICATIONS</div><h2 id="dialogTitle">Operational attention</h2><p>Fictional notices from the local sample workspace.</p></div><div class="alert-item"><span class="alert-mark amber">!</span><div><strong>Custodian evidence pending</strong><small>STL-2025-03812 · 09:32 UTC</small></div></div><div class="alert-item"><span class="alert-mark red">!</span><div><strong>Insurance evidence review</strong><small>Crown Custody · CMP-2025-0071</small></div></div>`);break;case"about":showAbout();break;case"filters":toast("Use status tabs or global search to inspect sample fixtures.");break;case"blocked":toast("Unavailable in prototype · no transaction or operational action was performed.");break;case"policy":dialog(`<div class="dialog-head"><button class="dialog-close" data-action="close">×</button><div class="eyebrow">POLICY REFERENCE · DEMO</div><h2 id="dialogTitle">Reserve risk limits</h2><p>Illustrative policy excerpt, not an approved mandate.</p></div><div class="record-detail-grid"><div><span>Gold concentration</span><strong>Maximum 35% · sample</strong></div><div><span>Counterparty</span><strong>Maximum $600M · sample</strong></div><div><span>Intraday settlement</span><strong>Maximum $750M · sample</strong></div><div><span>Authority</span><strong>Not configured</strong></div></div>`);break;case"goto-audit":page="Audit center";render();break;}});
$("#globalSearch").addEventListener("input",e=>search(e.target.value.trim()));$("#globalSearch").addEventListener("keydown",e=>{if(e.key==="Enter")$("#searchResults [data-action=search-record]")?.click()});document.addEventListener("keydown",e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();$("#globalSearch").focus()}if(e.key==="Escape"){$("#searchResults").hidden=true;$("#sidebar").classList.remove("sidebar-open")}});document.addEventListener("click",e=>{if(!e.target.closest(".global-search-wrap"))$("#searchResults").hidden=true});$("#appDialog").addEventListener("click",e=>{if(e.target===$("#appDialog"))$("#appDialog").close()});$("#appDialog").addEventListener("close",()=>$("#dialogContent").replaceChildren());
window.VeritasGoldDemo={get state(){return{persona,page,environment:"Sandbox",synthetic:true,liveIntegrations:false}}};render();
